export default class ProductSearched {
    constructor(details) {
        const isObject = typeof details === 'object' && details !== null;
        this.query = isObject ? details.query : details;
        this.total = isObject ? details.total : undefined;
    }

    toSegment() {
        const properties = { query: this.query };
        if (this.total !== undefined && this.total !== null) {
            properties.total_results = Number(this.total);
        }
        return {
            event: 'Products Searched',
            properties
        };
    }
}
